                while (k1 > 0) {
                        result = append_elements(asn1_struct, asn1_rdn_name, &out_str, k1, k1==1?1:0);
                        if (result < 0) {
                                gnutls_assert();
                                goto cleanup;
                        }
                        k1--;
                }
        }

        return _gnutls_buffer_to_datum(&out_str, dn, 1);

